<?php
namespace App\Services\Dapcode; use Illuminate\Support\Facades\File; use Illuminate\Support\Str; class SourceMapVaultService { protected static $vaultPath; public static function getVaultPath() { if ( ! static ::$vaultPath) { static ::$vaultPath = storage_path('app/dapcode/.sourcemaps'); } if ( ! File::isDirectory(static ::$vaultPath)) { File::makeDirectory(static ::$vaultPath, 0700, true, true); } return static ::$vaultPath; } public static function getVaultKey($filePath) { $relPath = str_replace('\\', '/', Str::after($filePath, base_path() . DIRECTORY_SEPARATOR)); return md5($relPath) . '.dapmap'; } public static function storeMap($filePath, $originalContent, $minifiedContent) { $vaultDir = static ::getVaultPath(); $vaultKey = static ::getVaultKey($filePath); $vaultFile = $vaultDir . DIRECTORY_SEPARATOR . $vaultKey; $lines = substr_count($originalContent, "\n") + 1; $isOriginal = ($lines > 2) || strlen($originalContent) < 100; if (File::isFile($vaultFile) && ! $isOriginal) { return true; } $relPath = str_replace('\\', '/', Str::after($filePath, base_path() . DIRECTORY_SEPARATOR)); $instId = InstallationService::getInstallationId(); $compressed = gzdeflate($originalContent, 9); $encodedPayload = base64_encode($compressed !== false ? $compressed : $originalContent); $data = [ 'file' => $relPath, 'orig_hash' => hash('sha256', $originalContent), 'mini_hash' => hash('sha256', $minifiedContent), 'inst_id' => $instId, 'created_at' => time(), 'payload' => $encodedPayload, 'checksum' => hash_hmac('sha256', $encodedPayload, $instId . '|DAPCODE-SOURCEMAP-V1'), ]; $json = json_encode($data); File::put($vaultFile, $json); @chmod($vaultFile, 0600); return true; } public static function hasMap($filePath) { $vaultDir = static ::getVaultPath(); $vaultKey = static ::getVaultKey($filePath); $vaultFile = $vaultDir . DIRECTORY_SEPARATOR . $vaultKey; return File::isFile($vaultFile); } public static function restoreOriginal($filePath) { $vaultDir = static ::getVaultPath(); $vaultKey = static ::getVaultKey($filePath); $vaultFile = $vaultDir . DIRECTORY_SEPARATOR . $vaultKey; if ( ! File::isFile($vaultFile)) { return null; } $json = File::get($vaultFile); $data = @json_decode($json, true); if ( ! is_array($data) || empty($data['payload'])) { return null; } $instId = InstallationService::getInstallationId(); $expectedChecksum = hash_hmac('sha256', $data['payload'], $instId . '|DAPCODE-SOURCEMAP-V1'); if ( ! hash_equals($expectedChecksum, (string) ($data['checksum'] ?? ''))) { return null; } $decoded = base64_decode($data['payload']); $uncompressed = @gzinflate($decoded); return $uncompressed !== false ? $uncompressed : $decoded; } public static function cleanMap($filePath) { $vaultDir = static ::getVaultPath(); $vaultKey = static ::getVaultKey($filePath); $vaultFile = $vaultDir . DIRECTORY_SEPARATOR . $vaultKey; if (File::isFile($vaultFile)) { return File::delete($vaultFile); } return false; } public static function cleanAllMaps() { $vaultDir = static ::getVaultPath(); $count = 0; if (File::isDirectory($vaultDir)) { foreach (File::files($vaultDir) as $file) { if ($file->getExtension() === 'dapmap') { File::delete($file->getRealPath()); $count++; } } } return $count; } }